//! Models of the `f32`/`f64` operations that the evaluator and the dtype
//! semantics call (floats as bits):
//! - `max`/`min`: aarch64 `FMAXNM`/`FMINNM` (a platform assumption; Rust leaves
//!   the sign of a zero result and NaN payloads unspecified), checked bit for bit
//!   on every pair of signed zeros, ones, quiet/signaling NaNs and infinity;
//! - `ceil`, `round_ties_even`, `sqrt`, `mul_add`: exact IEEE models (a NaN
//!   result is compared as NaN only: Rust leaves its payload unspecified);
//! - `sin`, `cos`, `tan`, `atan`, `exp`, `ln`: platform libm, extracted to
//!   opaque functions whose values are never checked (verification/trusted_base.json).
//! Dense native/Lean agreement of the exact operations is checked by
//! float_model_oracle.rs against FloatModelChecks.lean.

pub fn max_min64(x: u64, y: u64) -> (u64, u64) {
    let (x, y) = (f64::from_bits(x), f64::from_bits(y));
    (x.max(y).to_bits(), x.min(y).to_bits())
}

pub fn max_min32(x: u32, y: u32) -> (u32, u32) {
    let (x, y) = (f32::from_bits(x), f32::from_bits(y));
    (x.max(y).to_bits(), x.min(y).to_bits())
}

pub fn rounding64(x: u64) -> (u64, u64, u64) {
    let x = f64::from_bits(x);
    (x.ceil().to_bits(), x.round_ties_even().to_bits(), x.sqrt().to_bits())
}

pub fn rounding32(x: u32) -> (u32, u32, u32) {
    let x = f32::from_bits(x);
    (x.ceil().to_bits(), x.round_ties_even().to_bits(), x.sqrt().to_bits())
}

pub fn fma64(x: u64, a: u64, b: u64) -> u64 {
    f64::from_bits(x).mul_add(f64::from_bits(a), f64::from_bits(b)).to_bits()
}

pub fn fma32(x: u32, a: u32, b: u32) -> u32 {
    f32::from_bits(x).mul_add(f32::from_bits(a), f32::from_bits(b)).to_bits()
}

/// The libm functions, by operation code (0 sin, 1 cos, 2 tan, 3 atan, 4 exp,
/// otherwise ln). Extraction only: their values are unconstrained.
pub fn transcendental64(x: u64, op: u8) -> u64 {
    let x = f64::from_bits(x);
    match op {
        0 => x.sin(),
        1 => x.cos(),
        2 => x.tan(),
        3 => x.atan(),
        4 => x.exp(),
        _ => x.ln(),
    }
    .to_bits()
}

/// As `transcendental64`, for `f32`.
pub fn transcendental32(x: u32, op: u8) -> u32 {
    let x = f32::from_bits(x);
    match op {
        0 => x.sin(),
        1 => x.cos(),
        2 => x.tan(),
        3 => x.atan(),
        4 => x.exp(),
        _ => x.ln(),
    }
    .to_bits()
}

