    fn nan64(b: u64) -> u64 {
        if f64::from_bits(b).is_nan() { u64::MAX } else { b }
    }

    fn nan32(b: u32) -> u32 {
        if f32::from_bits(b).is_nan() { u32::MAX } else { b }
    }

    #[test]
    fn max_min_is_fmaxnm() {
        for (x, y, max, min) in MAX_MIN64 {
            assert_eq!(max_min64(black_box(x), black_box(y)), (max, min), "{x:#x} {y:#x}");
        }
        for (x, y, max, min) in MAX_MIN32 {
            assert_eq!(max_min32(black_box(x), black_box(y)), (max, min), "{x:#x} {y:#x}");
        }
    }

    #[test]
    fn exact_operations() {
        for (x, ceil, even, sqrt) in ROUNDING64 {
            let (c, e, s) = rounding64(black_box(x));
            assert_eq!((nan64(c), nan64(e), nan64(s)), (ceil, even, sqrt), "{x:#x}");
        }
        for (x, ceil, even, sqrt) in ROUNDING32 {
            let (c, e, s) = rounding32(black_box(x));
            assert_eq!((nan32(c), nan32(e), nan32(s)), (ceil, even, sqrt), "{x:#x}");
        }
        for (x, a, b, r) in FMA64 {
            assert_eq!(nan64(fma64(black_box(x), black_box(a), black_box(b))), r, "{x:#x}");
        }
        for (x, a, b, r) in FMA32 {
            assert_eq!(nan32(fma32(black_box(x), black_box(a), black_box(b))), r, "{x:#x}");
        }
    }

    #[test]
    fn transcendentals_extract() {
        // Values are platform libm results: only that each operation runs.
        for op in 0..6 {
            black_box(transcendental64(black_box(1.0f64.to_bits()), op));
            black_box(transcendental32(black_box(1.0f32.to_bits()), op));
        }
    }
